const dictionaries = {
  en: { ...en, ...productCopy.en },
  he: { ...he, ...productCopy.he },
  ar: { ...ar, ...productCopy.ar },
};

interface I18nValue {
  language: AppLanguage;
  setLanguage: (language: AppLanguage) => void;
  rtl: boolean;
  t: (key: string, params?: Params) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

function interpolate(value: string, params?: Params): string {
  if (!params) return value;
  return Object.entries(params).reduce((current, [key, replacement]) => current.split(`{${key}}`).join(String(replacement)), value);
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<AppLanguage>("en");
  useEffect(() => {
    if (typeof document === "undefined") return;
    document.documentElement.lang = language;
    document.documentElement.dir = language === "he" || language === "ar" ? "rtl" : "ltr";
  }, [language]);
  const value = useMemo<I18nValue>(() => ({
    language,
    setLanguage,
    rtl: language === "he" || language === "ar",
    t: (key, params) => interpolate(dictionaries[language][key] || dictionaries.en[key] || key, params),
  }), [language]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const context = useContext(I18nContext);
  if (!context) throw new Error("useI18n must be used inside I18nProvider");
  return context;
}

