const dayNames: Record<AppLanguage, string[]> = {
  en: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
  he: ["יום שני", "יום שלישי", "יום רביעי", "יום חמישי", "יום שישי", "שבת", "יום ראשון"],
  ar: ["الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت", "الأحد"],
};

export function localizedPostType(postType: string, language: AppLanguage): string {
  return postTypes[language][postType] || postType.split("_").join(" ");
}

export function localizedDay(index: number, language: AppLanguage, short = false): string {
  const value = dayNames[language][index] || "";
  return short ? value.slice(0, language === "en" ? 2 : 3) : value;
}

