export function localizeRecommendation(item: ProfessionalRecommendation, language: AppLanguage): ProfessionalRecommendation {
  if (language === "en") return item;
  const copy = recommendationCopy[item.id]?.[language];
  const validation = validationCopy[item.id]?.[language] || item.validation;
  if (!copy) return { ...item, validation };
  return { ...item, ...copy, validation };
}

export function localizeStrength(value: string, language: AppLanguage): string {
  if (language === "en") return value;
  const key = value.toLowerCase();
  const heValue = key.includes("above the current decision") ? "אותות התמונה והכיתוב יחד נמצאים מעל סף ההחלטה הנוכחי."
    : key.includes("close to the current decision") ? "הטיוטה קרובה לגבול ההחלטה, ולכן כדאי לבדוק שיפור ממוקד."
    : key.includes("caption provides") ? "הכיתוב מספק מספיק מקום להעברת רעיון שלם."
    : key.includes("emotional tone") ? "לניסוח יש טון רגשי ברור מספיק לסוג התוכן."
    : key.includes("consistent message") ? "התמונה והכיתוב מעבירים מסר עקבי במידה סבירה."
    : "הפוסט נבדק בהצלחה באמצעות אותות התמונה והכיתוב.";
  const arValue = key.includes("above the current decision") ? "تقع إشارات الصورة والنص معًا فوق حد القرار الحالي."
    : key.includes("close to the current decision") ? "المسودة قريبة من حد القرار، لذا يستحق تحسين مركّز الاختبار."
    : key.includes("caption provides") ? "يوفر النص مساحة كافية لتوصيل فكرة مكتملة."
    : key.includes("emotional tone") ? "تحمل الصياغة نبرة عاطفية واضحة بما يكفي لهذا المحتوى."
    : key.includes("consistent message") ? "تنقل الصورة والنص رسالة متناسقة بصورة معقولة."
    : "تم تقييم المنشور بنجاح باستخدام إشارات الصورة والنص.";
  return language === "he" ? heValue : arValue;
}

